"use strict";(globalThis.webpackChunkkonflux_website=globalThis.webpackChunkkonflux_website||[]).push([[735],{1099(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"welcome-to-new-home","metadata":{"permalink":"/konflux-ci.github.io/blog/welcome-to-new-home","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-03-16-welcome-to-konflux/index.md","source":"@site/blog/2026-03-16-welcome-to-konflux/index.md","title":"Welcome to the New Home of Konflux CI","description":"We\'re excited to introduce the new home for Konflux CI! This website is now your central hub for everything Konflux \u2014 documentation, architecture details, getting started guides, and community resources.","date":"2026-03-16T00:00:00.000Z","tags":[{"inline":true,"label":"announcement","permalink":"/konflux-ci.github.io/blog/tags/announcement"},{"inline":false,"label":"website","permalink":"/konflux-ci.github.io/blog/tags/website","description":"Website tag description"}],"readingTime":1.1,"hasTruncateMarker":true,"authors":[{"name":"Konflux Team","title":"Konflux CI Team","url":"https://konflux-ci.dev","page":{"permalink":"/konflux-ci.github.io/blog/authors/konflux-team"},"socials":{"github":"https://github.com/konflux-ci"},"imageURL":"https://github.com/konflux-ci.png","key":"konflux-team"}],"frontMatter":{"slug":"welcome-to-new-home","title":"Welcome to the New Home of Konflux CI","authors":["konflux-team"],"tags":["announcement","website"]},"unlisted":false},"content":"We\'re excited to introduce the new home for Konflux CI! This website is now your central hub for everything Konflux \u2014 documentation, architecture details, getting started guides, and community resources.\\n\\n\x3c!-- truncate --\x3e\\n\\n## A Fresh Start\\n\\nAfter careful planning and development, we\'ve launched this new website to provide a better experience for the Konflux community. Whether you\'re a first-time visitor or a long-time contributor, you\'ll find everything you need in one place.\\n\\n## What You\'ll Find Here\\n\\n### Documentation\\n\\nOur comprehensive documentation covers everything from initial setup to advanced configurations. Head over to the [documentation](/docs/intro) to explore guides, API references, and best practices.\\n\\n### Architecture & Design\\n\\nWant to understand how Konflux works under the hood? We\'ve included detailed architecture information and design decisions that power the platform.\\n\\n### Getting Started\\n\\nNew to Konflux? Check out our [Getting Started guide](/getting-started) for a step-by-step walkthrough that will have you up and running quickly.\\n\\n### Community & Contributions\\n\\nKonflux is an open source project, and we welcome contributions from the community. Stay tuned for more resources on how to get involved.\\n\\n## What\'s Next\\n\\nThis is just the beginning. We\'ll be regularly updating this site with new content, tutorials, and resources. Keep an eye on this blog for announcements, updates, and insights from the Konflux team.\\n\\nWe\'re glad you\'re here. Welcome home!\\n\\n\u2014 The Konflux Team"}]}}')}}]);